-- Original educational reading with verified background references (2026-10-18).
-- Not clinical guidance or professional endorsement. Never overwrites admin edits.
begin;
insert into public.article_categories(id,name,slug,description,icon,display_order) values
('60000000-0000-4000-8000-000000000001','Eye Health','eye-health','Comfortable viewing and thoughtful screen breaks.','Eye',1),
('60000000-0000-4000-8000-000000000002','Posture & Ergonomics','posture-ergonomics','Explore your workstation and opportunities to change position.','PersonStanding',2),
('60000000-0000-4000-8000-000000000003','Sleep Habits','sleep-habits','Build an evening routine that suits your circumstances.','Moon',3),
('60000000-0000-4000-8000-000000000004','Digital Fatigue','digital-fatigue','Make space to reflect on your digital workload.','Leaf',4),
('60000000-0000-4000-8000-000000000005','Healthy Digital Habits','healthy-digital-habits','Choose practical boundaries and sustainable routines.','Sparkles',5),
('60000000-0000-4000-8000-000000000006','General Wellness','general-wellness','Small choices for a balanced day.','Heart',6)
on conflict do nothing;
insert into public.article_tags(id,name,slug) values
('62000000-0000-4000-8000-000000000001','Screen breaks','screen-breaks'),
('62000000-0000-4000-8000-000000000002','Workstation','workstation'),
('62000000-0000-4000-8000-000000000003','Evening routine','evening-routine'),
('62000000-0000-4000-8000-000000000004','Intentional technology','intentional-technology'),
('62000000-0000-4000-8000-000000000005','Movement','movement'),
('62000000-0000-4000-8000-000000000006','Reflection','reflection')
on conflict do nothing;

do $seed$
declare item jsonb; doc jsonb; category uuid; inserted uuid; words int; text_content text; tag_slug text;
begin
for item in select value from jsonb_array_elements($articles$[
 {"id":"61000000-0000-4000-8000-000000000001","title":"Understanding Digital Eye Discomfort","slug":"understanding-digital-eye-discomfort","category":"eye-health","summary":"Notice patterns in screen comfort and prepare useful questions about your viewing setup.","intro":"Screen comfort is personal. This guide offers a place to notice when a task feels uncomfortable without using those observations to diagnose a condition. Start with a typical reading or study task and describe what you are doing: the device, the lighting, the text size, and whether you can change position. A few practical notes can make your next workstation review more specific.","tips":["Record the task and surroundings when discomfort appears, rather than assigning yourself a diagnosis.","Check whether text is comfortably readable and whether reflections make the display harder to view.","Choose a natural stopping point to pause the screen task and review your setup.","Keep a short list of questions to discuss with an eye-care professional if concerns persist."],"outro":"Choose one observation to make today. For example, compare how the same document looks at a larger text size. This is a personal comfort check, not an eye test. If discomfort persists, changes suddenly, or worries you, seek appropriate professional advice instead of relying on an app to interpret it.","source":"https://www.osha.gov/etools/computer-workstations/checklists/evaluation","source_title":"Computer Workstations: Evaluation Checklist","publisher":"OSHA","tags":["workstation","reflection"],"featured":true},
 {"id":"61000000-0000-4000-8000-000000000002","title":"Practical Screen Break Habits","slug":"practical-screen-break-habits","category":"eye-health","summary":"Create a visual-pause routine that fits the tasks and responsibilities in your day.","intro":"A break routine works best when its cue makes sense in your actual day. List a few natural transitions: finishing a page, ending a call, or saving a piece of work. These are opportunities to pause without turning the whole day into a rigid timetable. ScreenWise can remind you about a pause, but you decide when it is safe and appropriate to take it.","tips":["Choose one task transition as a cue to stop looking at the same display.","Use the visual-break timer if a timed reminder suits you, and adjust its focus interval.","Save a completion only after taking the break; a countdown is not proof of participation.","Review reminder volume after a few days and switch off prompts that are becoming distracting."],"outro":"Try a simple experiment: use one reminder during a familiar work period, then write down whether the timing was practical. If it interrupted an important task, change the cue or interval. Missing a reminder is information for planning your routine, not a reason to invent a completed break or judge your day.","source":"https://www.osha.gov/computer-workstations","source_title":"Computer Workstations: Overview","publisher":"OSHA","tags":["screen-breaks","reflection"],"featured":false},
 {"id":"61000000-0000-4000-8000-000000000003","title":"Setting Up an Ergonomic Workstation","slug":"setting-up-an-ergonomic-workstation","category":"posture-ergonomics","summary":"Review your desk as a connected setup, with attention to support, reach, and readability.","intro":"A workstation review is more useful when you consider the whole task rather than searching for one perfect pose. Notice how the chair, work surface, keyboard, pointing device, and display work together. OSHA provides a structured workstation checklist that can guide that review. This article turns that idea into a short personal planning exercise; it does not certify a setup or replace a workplace assessment.","tips":["Write down which equipment you can adjust and which changes require workplace assistance.","Review whether frequently used items are easy to reach without an awkward repeated movement.","Check whether you can read the display comfortably while using available chair and foot support.","Make one manageable adjustment, then reassess the task instead of changing everything at once."],"outro":"Keep the notes for your next desk review. You may find that one setup works for typing while a different arrangement suits reading or calls. Discuss equipment limitations with the appropriate workplace contact. There is no need to purchase a product just because an article mentions ergonomics; begin with a clear description of the task and what feels difficult.","source":"https://www.osha.gov/etools/computer-workstations/checklists/evaluation","source_title":"Computer Workstations: Evaluation Checklist","publisher":"OSHA","tags":["workstation","reflection"],"featured":true},
 {"id":"61000000-0000-4000-8000-000000000004","title":"Healthy Movement Habits During Desk Work","slug":"healthy-movement-habits-during-desk-work","category":"posture-ergonomics","summary":"Find comfortable opportunities to change position without turning every pause into a workout.","intro":"A desk day contains small transitions that can become opportunities for a change of position. Think about the space you have, the tasks you need to complete, and any mobility considerations. The aim of this planning exercise is a practical routine you can adapt, rather than a fixed movement prescription or a promise that one stretch will resolve discomfort.","tips":["Choose a safe space and a movement option suited to your abilities and circumstances.","Consider a position change between tasks when your work and surroundings permit it.","Use a guided activity only if the instructions feel comfortable and relevant to you.","Stop an activity that causes pain or discomfort rather than trying to finish for a streak."],"outro":"Pick one natural transition to try this week. You could plan a brief standing pause or choose a seated alternative. Review what was manageable and change the plan when your schedule or needs change. A completed session is a self-reported record of participation, not a measurement of exercise quality or a clinical outcome.","source":"https://www.who.int/news-room/fact-sheets/detail/physical-activity","source_title":"Physical activity","publisher":"World Health Organization","tags":["movement","workstation"],"featured":false},
 {"id":"61000000-0000-4000-8000-000000000005","title":"Building a Consistent Evening Routine","slug":"building-a-consistent-evening-routine","category":"sleep-habits","summary":"Design a small evening checklist around the responsibilities and quiet moments you actually have.","intro":"The CDC includes consistent bed and wake times among its suggestions for sleep habits. Translating that general advice into a personal plan starts with your circumstances: work hours, study, caring responsibilities, and the routines you already follow. Choose a manageable evening action rather than setting an ambitious schedule that does not fit your life.","tips":["List the evening tasks you need to keep, then identify a realistic place for a quiet transition.","Choose one repeatable action, such as preparing for tomorrow or reviewing your device settings.","Set an evening reminder only on the days and during the hours when it will be useful.","Record the routine you completed without treating it as evidence of how long or how well you slept."],"outro":"Review the plan after a few evenings. Keep what was practical and simplify what was not. A routine can be adjusted without being considered a failure. If you regularly have difficulty sleeping or have concerns about your sleep, discuss them with a healthcare professional; an activity checklist cannot diagnose the cause.","source":"https://www.cdc.gov/sleep/about/","source_title":"About Sleep","publisher":"CDC","tags":["evening-routine","reflection"],"featured":true},
 {"id":"61000000-0000-4000-8000-000000000006","title":"Understanding Screens and Sleep Habits","slug":"understanding-screens-and-sleep-habits","category":"sleep-habits","summary":"Explore the place digital tasks occupy in your evening without assuming an app can measure your sleep.","intro":"Looking at evening technology use can help you describe your routine more clearly. Separate essential tasks, such as contacting family, from activities you would prefer to finish earlier. The CDC lists turning off electronic devices before bedtime as one sleep-habit suggestion. Your personal plan should also account for accessibility needs, essential contacts, and other responsibilities.","tips":["Choose a point in the evening to review which digital tasks still need attention.","Decide which alerts must remain available before silencing anything on a shared or essential device.","Prepare an offline alternative you would like to try, without making it another demanding task.","Use the evening checklist to record actions, not to estimate sleep duration or sleep quality."],"outro":"Try one small change and note whether it was practical. The purpose is to make an intentional choice, not to promise a particular sleep result. If the plan clashes with your responsibilities, adjust it. For ongoing sleep difficulties, seek individual advice rather than treating a device setting or a saved app streak as a solution.","source":"https://www.cdc.gov/sleep/about/","source_title":"About Sleep","publisher":"CDC","tags":["evening-routine","intentional-technology"],"featured":false},
 {"id":"61000000-0000-4000-8000-000000000007","title":"Recognizing Digital Fatigue","slug":"recognizing-digital-fatigue","category":"digital-fatigue","summary":"Use everyday observations to review demanding digital routines without assigning a medical label.","intro":"Digital fatigue is used in everyday conversation to describe feeling worn out by digital tasks. In this library it is a reflection topic, not a diagnosis or a measured health condition. Rather than scoring yourself from a single feeling, describe the work: the number of transitions, the alerts, and the tasks that occupied your attention. That description is a useful starting point for deciding what to change.","tips":["Write down a demanding task and what made it difficult to manage that day.","Distinguish workload, interruptions, and physical comfort instead of assuming one explanation fits everything.","Choose one boundary or pause you would like to test during a similar task.","Reach out to an appropriate person when work demands or concerns need more support than a personal reminder."],"outro":"Review your notes with curiosity. A busy day does not need to become a permanent label. Use the observations to make a small plan or prepare a conversation about workload. The NHS wellbeing resource below offers broader reading and support options; this article does not replace assessment or personalized help.","source":"https://www.nhs.uk/every-mind-matters/mental-wellbeing-tips/","source_title":"Mental wellbeing tips","publisher":"NHS","tags":["reflection","intentional-technology"],"featured":false},
 {"id":"61000000-0000-4000-8000-000000000008","title":"Managing Notification Overload","slug":"managing-notification-overload","category":"digital-fatigue","summary":"Audit alerts deliberately while keeping essential messages and accessibility needs in view.","intro":"A notification audit is a practical organization task. Begin by noticing which alerts help you make a timely decision and which ones can wait. Different devices and responsibilities need different settings, so avoid copying another person’s configuration without considering your own needs. This guide suggests an experiment with your attention settings; it does not make a claim about treating stress or any other condition.","tips":["Choose one application and review the notification categories it currently sends.","Keep necessary contacts and safety-critical messages available before changing other alert settings.","Consider a planned time for nonurgent updates if your role and circumstances permit it.","Review ScreenWise reminders too, so wellness prompts do not become another source of unwanted alerts."],"outro":"After trying a change, check whether you missed anything important and whether the setting was useful. Restore or adapt it when needed. Shared devices and workplace-managed applications may require another person’s agreement. For broader wellbeing concerns, use appropriate support resources rather than expecting notification settings alone to resolve them.","source":"https://www.nhs.uk/every-mind-matters/mental-wellbeing-tips/","source_title":"Mental wellbeing tips","publisher":"NHS","tags":["intentional-technology","reflection"],"featured":false},
 {"id":"61000000-0000-4000-8000-000000000009","title":"Creating Healthy Technology Boundaries","slug":"creating-healthy-technology-boundaries","category":"healthy-digital-habits","summary":"Turn a vague intention into a small, clearly described choice about when and how you use technology.","intro":"A technology boundary is easier to review when you can describe the action. Instead of an open-ended promise to use devices less, name a task, a time, or a situation where you would like a different choice. The boundary can be modest and flexible. Its purpose is to support your own priorities, not to enforce a universal amount of screen use or judge another person’s routine.","tips":["Write down one situation where you want to make a more intentional device choice.","Describe an alternative action that is realistic in that situation and accessible to you.","Tell relevant people about the plan when a change could affect shared work or communication.","Choose a review date and decide what information would help you keep, change, or stop the experiment."],"outro":"A useful boundary may change across workdays, weekends, and busy periods. Keep necessary exceptions visible rather than pretending they do not exist. You can use a saved reflection activity to remember the review. The background resource discusses workstation considerations; it is not evidence for a particular screen-time limit or a guarantee about your personal outcomes.","source":"https://www.osha.gov/computer-workstations","source_title":"Computer Workstations: Overview","publisher":"OSHA","tags":["intentional-technology","reflection"],"featured":false},
 {"id":"61000000-0000-4000-8000-000000000010","title":"Building Sustainable Break Routines","slug":"building-sustainable-break-routines","category":"healthy-digital-habits","summary":"Choose cues, activities, and targets that remain useful when your schedule changes.","intro":"A sustainable break plan is one you can revisit. Start by choosing a cue and an activity that fit a normal day, then think about what changes on a busy day. You might keep a shorter alternative or pause the goal temporarily. Planning those options in advance makes the routine easier to discuss and adjust without inventing completion records or treating a missed target as a verdict.","tips":["Pair a familiar task transition with an activity you have read and understand.","Choose a small daily or weekly target and check which activities actually count toward it.","Pause a goal when it is not appropriate, and review how paused dates affect its tracking.","Look at recorded history to evaluate the plan instead of chasing a streak at the expense of comfort."],"outro":"Use the first week as a trial. Keep notes about timing, available space, and useful alternatives. A saved session simply records your confirmation that you participated. It does not establish that the plan produced a health benefit. The workstation resource can support a broader review of your work environment alongside your own planning notes.","source":"https://www.osha.gov/computer-workstations","source_title":"Computer Workstations: Overview","publisher":"OSHA","tags":["screen-breaks","intentional-technology"],"featured":false},
 {"id":"61000000-0000-4000-8000-000000000011","title":"Balancing Digital Work and Physical Activity","slug":"balancing-digital-work-and-physical-activity","category":"general-wellness","summary":"Make a practical map of your day and identify movement opportunities suited to your circumstances.","intro":"WHO provides general information about physical activity and sedentary behaviour. Applying broad guidance to your own day requires attention to abilities, responsibilities, access, and any individualized advice you already receive. This article is a scheduling reflection: it helps you identify where an appropriate activity might fit rather than prescribing an exercise programme or measuring your activity automatically.","tips":["Map the main blocks of your day, including travel, study, work, and caring tasks.","Identify an opportunity for an activity that suits your current abilities and available environment.","Keep an alternative for days when the original plan is impractical or uncomfortable.","Separate short self-reported app sessions from any broader activity plan or professional recommendations."],"outro":"Choose one opportunity to explore and decide when you will review it. You may need a change in workload, equipment, or support rather than another reminder. Adapt your plan as circumstances change. If you need advice about what activity is suitable for you, seek individual guidance instead of using this article as a personal exercise prescription.","source":"https://www.who.int/news-room/fact-sheets/detail/physical-activity","source_title":"Physical activity","publisher":"World Health Organization","tags":["movement","reflection"],"featured":false},
 {"id":"61000000-0000-4000-8000-000000000012","title":"Developing a Personal Wellness Routine","slug":"developing-a-personal-wellness-routine","category":"general-wellness","summary":"Bring together one useful observation, a manageable action, and a clear opportunity to review it.","intro":"A personal routine does not need to cover every part of life at once. Choose one topic that matters to you, such as a work transition or an evening task. Describe what you want to try and what would make it manageable. This is an exercise in planning and reflection, not a personalized health assessment or a claim that a routine can prevent or treat a condition.","tips":["Choose one priority from your own circumstances rather than activating every suggested goal.","Read the activity instructions and decide whether the action is appropriate and comfortable for you.","Set a target you understand, including the timezone and the activities that count toward it.","Review the plan regularly and ask for support when a concern needs more than self-directed planning."],"outro":"Keep the routine small enough to explain in a sentence. If it stops being useful, edit or archive it while preserving the records you already saved. You can return to broader resources for ideas, but their general guidance does not replace advice based on your circumstances. The point is a considered next step, not a perfect dashboard.","source":"https://www.nhs.uk/every-mind-matters/mental-wellbeing-tips/","source_title":"Mental wellbeing tips","publisher":"NHS","tags":["reflection","intentional-technology"],"featured":false}
]$articles$::jsonb) loop
  select id into category from public.article_categories where slug=item->>'category';
  if category is null then continue;end if;
  doc=jsonb_build_object('type','doc','content',jsonb_build_array(
    jsonb_build_object('type','heading','attrs',jsonb_build_object('level',2),'content',jsonb_build_array(jsonb_build_object('type','text','text','Understand your routine'))),
    jsonb_build_object('type','paragraph','content',jsonb_build_array(jsonb_build_object('type','text','text',item->>'intro'))),
    jsonb_build_object('type','heading','attrs',jsonb_build_object('level',2),'content',jsonb_build_array(jsonb_build_object('type','text','text','Try one small change'))),
    jsonb_build_object('type','bulletList','content',(select jsonb_agg(jsonb_build_object('type','listItem','content',jsonb_build_array(jsonb_build_object('type','paragraph','content',jsonb_build_array(jsonb_build_object('type','text','text',tip)))))) from jsonb_array_elements_text(item->'tips') t(tip))),
    jsonb_build_object('type','heading','attrs',jsonb_build_object('level',2),'content',jsonb_build_array(jsonb_build_object('type','text','text','Reflect and adapt'))),
    jsonb_build_object('type','paragraph','content',jsonb_build_array(jsonb_build_object('type','text','text',item->>'outro'))),
    jsonb_build_object('type','blockquote','content',jsonb_build_array(jsonb_build_object('type','paragraph','content',jsonb_build_array(jsonb_build_object('type','text','text','Use these ideas for general education. Stop uncomfortable activities and seek appropriate professional advice for persistent or concerning symptoms.')))))
  ));
  text_content=concat_ws(' ','Understand your routine',item->>'intro','Try one small change',(select string_agg(tip,' ') from jsonb_array_elements_text(item->'tips') t(tip)),'Reflect and adapt',item->>'outro','Use these ideas for general education. Stop uncomfortable activities and seek appropriate professional advice for persistent or concerning symptoms.');
  words=cardinality(regexp_split_to_array(trim(text_content),'\s+'));
  inserted=null;
  insert into public.articles(id,title,slug,summary,category_id,content,word_count,reading_time_minutes,status,is_featured,sources,editorial_reviewed,published_at)
  values((item->>'id')::uuid,item->>'title',item->>'slug',item->>'summary',category,doc,words,greatest(1,ceil(words/200.0)::int),'PUBLISHED',(item->>'featured')::boolean,
    jsonb_build_array(jsonb_build_object('title',item->>'source_title','source_url',item->>'source','publisher',item->>'publisher')),true,'2026-10-18T03:30:00Z')
  on conflict do nothing returning id into inserted;
  if inserted is not null then
    for tag_slug in select jsonb_array_elements_text(item->'tags') loop
      insert into public.article_tag_links(article_id,tag_id) select inserted,id from public.article_tags where slug=tag_slug on conflict do nothing;
    end loop;
  end if;
end loop;
end;$seed$;
commit;
